    objective: { en: "To teach hobbies and tag questions for natural conversation in a contextualized way.", pt: "Ensinar hobbies e tag questions para uma conversação natural de forma contextualizada." },
    communicationGoal: { en: "The student will be able to use 'meetings' and hobby vocabulary to communicate in real situations.", pt: "O aluno será capaz de usar 'meetings' e o vocabulário de hobbies para se comunicar em situações reais." },
